using DVLD_Enterprise_System.Domain.Enums;

namespace DVLD_Enterprise_System.Application.DTOs;

public record PersonDto(
    int PersonID,
    string NationalNo,
    string FirstName,
    string SecondName,
    string? ThirdName,
    string LastName,
    DateTime DateOfBirth,
    Gender Gender,
    string Address,
    string Phone,
    string? Email,
    int NationalityCountryID,
    string? ImagePath);

/// <summary>
/// Everything needed to create a new Person. Notice it does NOT include
/// PersonID (auto-generated by the database).
/// </summary>
public record PersonCreateDto(
    string NationalNo,
    string FirstName,
    string SecondName,
    string? ThirdName,
    string LastName,
    DateTime DateOfBirth,
    Gender Gender,
    string Address,
    string Phone,
    string? Email,
    int NationalityCountryID,
    string? ImagePath);

/// <summary>
/// Fields a client is allowed to change on an existing Person.
/// We deliberately EXCLUDE NationalNo and DateOfBirth here as an example of a
/// business rule expressed through the DTO shape itself: a person's national ID
/// number and birth date should not be editable through a simple "update profile"
/// operation in a real system (they'd need a separate, audited correction process).
/// </summary>
public record PersonUpdateDto(
    string FirstName,
    string SecondName,
    string? ThirdName,
    string LastName,
    string Address,
    string Phone,
    string? Email,
    string? ImagePath);
